{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "In six cancer patients, niraparib had an absolute oral bioavailability of 72.7% (90% CI 61.69–83.40) after a 300 mg oral dose versus IV 14C-microdose, providing direct human evidence of high F for a heteroaromatic amide with a basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Ziprasidone had an absolute oral bioavailability of 59% in fed volunteers (20 mg oral vs 5 mg IV), supporting high F for a piperazine-containing heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Vardenafil, which shares the arylsulfonyl piperazine and fused heterocyclic lactam motif, had 34% oral bioavailability in healthy fasted volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Sildenafil, a close structural analogue with a sulfonyl piperazine and fused pyrimidinone, had an absolute oral bioavailability of 40% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Thalidomide, a lactam/imide drug, had an estimated oral bioavailability of 80–100% in humans, supporting high F for lactam-containing compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fenspiride, a basic amine drug with an oxazolidinone, had an absolute oral bioavailability of 90% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Didanosine oral solution with antacid in children with HIV had 19% bioavailability, just below the threshold, but this nucleoside has highly variable absorption and is structurally distant from the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Enteral sildenafil in an infant had 2.78% absolute bioavailability, but this was enteral administration in a critically ill infant and is not representative of standard oral bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F≥20%) because multiple high-transfer human absolute bioavailability measurements for structurally related heteroaromatic sulfonamide/piperazine and lactam drugs (sildenafil 40%, vardenafil 34%, ziprasidone 59%, niraparib 73%, thalidomide 80–100%) all exceed the threshold; the few sub-20% records are special populations/routes and do not outweigh the consistent high-F evidence.",
  "evidence_gaps": [
    "No direct experimental F measurement for the exact query molecule.",
    "The closest structural analogues (sildenafil/vardenafil) have F 34–40%, comfortably above 20%, but their first-pass metabolism and food effects are not fully mirrored in the query.",
    "The query's homopiperazine sulfonamide basicity and quinolinone lactam may alter permeability/efflux relative to piperazine analogues; no transporter or solubility data are available."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C38"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "niraparib"
    },
    {
      "applicability": "high",
      "card_ids": ["C01"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "ziprasidone"
    },
    {
      "applicability": "high",
      "card_ids": ["C29", "C27"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "PDE5 inhibitors"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C45"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "thalidomide"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C14"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "fenspiride"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C07"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "didanosine"
    },
    {
      "applicability": "low",
      "card_ids": ["C12"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "sildenafil enteral"
    }
  ],
  "revision_action": "initial"
}

